class Resource extends Base {
 mount(){this.selected=-1;this.render(`<section class="scene"><header><span class="label">FIELDWORK / SELECTED OBJECTS</span><h2>A collection worth opening.</h2><p class="hint">Three studies in space, form and feeling.</p></header><div class="deck"></div><div class="detail" aria-live="polite"><span class="label">SELECT A STUDY</span><p>Each object has a story. Open one to read its notes.</p></div></section>`,`.scene{background:var(--bg);border:1px solid var(--line);border-radius:var(--radius);padding:32px;min-height:510px}header h2{font-size:clamp(22px,4vw,32px);font-weight:500;letter-spacing:-1px;margin:10px 0}.deck{display:flex;gap:12px;height:240px;margin:27px 0 22px}.card{position:relative;flex:1;min-width:0;overflow:hidden;border:1px solid #ffffff18;padding:16px;text-align:left;color:#f0eadf;border-radius:11px;background:var(--art);display:flex;align-items:flex-end;transition:flex var(--deck-duration,.65s) cubic-bezier(.22,.8,.2,1)}.card.selected{flex:2.2}.card::before{content:'';position:absolute;width:60%;aspect-ratio:1;left:22%;top:15%;border-radius:50% 50% 0 0;background:linear-gradient(130deg,#fff9,#fff1);box-shadow:18px 20px 0 #0002;transform:rotate(-12deg)}.card:nth-child(2)::before{border-radius:6px;transform:rotate(35deg);background:linear-gradient(140deg,#e5c4a0,#8c654c)}.card:nth-child(3)::before{border-radius:50%;background:radial-gradient(ellipse at 35% 28%,#c7daaa,#4e6250 60%,#253d34);box-shadow:16px 15px 35px #0004}.card span{position:relative;z-index:1}.card small{display:block;font-size:9px;letter-spacing:1px;opacity:.7;margin-bottom:7px}.card strong{font-weight:500;font-size:18px}.detail{border-top:1px solid var(--line);padding-top:18px;display:grid;grid-template-columns:1fr 2fr;gap:18px;min-height:75px}.detail p{font-size:12px;color:var(--muted);line-height:1.8}@media(max-width:480px){.scene{padding:22px 16px}.deck{height:210px;gap:7px}.card{padding:12px 8px}.card strong{font-size:13px}.card small{font-size:7px}.detail{grid-template-columns:1fr;gap:9px}}`);this.draw();this.listen(this.$('.deck'),'click',e=>{const button=e.target.closest('button');if(button)this.select(Number(button.dataset.index));});}
 draw(){const variants={architecture:['Courtyard','Threshold','Observatory'],objects:['Arc lamp','Form chair','Quiet vessel'],places:['Open ground','Desert room','Greenhouse']};const titles=variants[this.text('variant','architecture')]||variants.architecture;this.items??=titles.map((title,i)=>({title,subtitle:`STUDY ${String(i+1).padStart(2,'0')}`,body:['A pause between inside and outside. Light draws the room before the walls do.','A useful object begins with a good question. This one asks how little is enough.','An invitation to pay attention. Texture, shadow and a slower way of seeing.'][i]}));this.$('.deck').innerHTML=this.items.map((item,i)=>`<button class="card ${i===this.selected?'selected':''}" data-index="${i}" aria-expanded="${i===this.selected}" style="--art:${['linear-gradient(150deg,#999b83,#40594d)','linear-gradient(145deg,#806a5b,#332d30)','linear-gradient(145deg,#6a7d6b,#1e3631)'][i%3]}"><span><small>${escape(item.subtitle)}</small><strong>${escape(item.title)}</strong></span></button>`).join('');}
 configured(name){if(name==='duration')this.$('.deck').style.setProperty('--deck-duration',this.number('duration',650,150,1200)+'ms');if(name==='variant'){this.items=null;this.selected=-1;this.draw();}}
 select(index){if(!this.items[index])return;this.selected=this.selected===index?-1:index;this.$$('.card').forEach((node,i)=>{node.classList.toggle('selected',i===this.selected);node.setAttribute('aria-expanded',String(i===this.selected));});const detail=this.items[this.selected];this.$('.detail').innerHTML=detail?`<span class="label">${escape(detail.title)}</span><p>${escape(detail.body)}</p>`:'<span class="label">SELECT A STUDY</span><p>Each object has a story. Open one to read its notes.</p>';this.tween(this.$('.detail'),[{opacity:.1,transform:'translateY(9px)'},{opacity:1,transform:'none'}]);this.emit('deck-change',{index:this.selected});}
}
